void fxGetNextTokenJSXChild(txParser* parser)
{
        txString p = parser->buffer;
        txString q = p + parser->bufferSize - 1;
        txString s = C_NULL;
        char c;
        txString after = C_NULL;
        txString before = C_NULL;
        txString text = C_NULL;
        parser->crlf2 = 0;
        parser->escaped2 = 0;
        parser->integer2 = 0;
        parser->modifierLength2 = 0;
        parser->modifier2 = parser->emptyString;
        parser->number2 = 0;
        parser->rawLength2 = 0;
        parser->raw2 = parser->emptyString;
        parser->stringLength2 = 0;
        parser->string2 = parser->emptyString;
        parser->symbol2 = C_NULL;
        parser->token2 = XS_NO_TOKEN;
        while (parser->token2 == XS_NO_TOKEN) {
                switch (parser->character) {
                case C_EOF:
                        parser->token2 = XS_TOKEN_EOF;
                        break;
                case 10:
                case 0x2028: // <LS>
                case 0x2029: // <PS>
                        parser->line2++;
                        p = fxUTF8Buffer(parser, parser->character, p, q);
                        fxGetNextCharacter(parser);
                        parser->crlf2 = 1;
                        break;
                case 13:
                        parser->line2++;
                        p = fxUTF8Buffer(parser, parser->character, p, q);
                        fxGetNextCharacter(parser);
                        if (parser->character == 10) {
                                p = fxUTF8Buffer(parser, parser->character, p, q);
                                fxGetNextCharacter(parser);
                        }
                        parser->crlf2 = 1;
                        break;

                case '<':
                        fxGetNextCharacter(parser);
                        parser->token2 = XS_TOKEN_LESS;
                        break;
                case '>':
                        fxGetNextCharacter(parser);
                        parser->token2 = XS_TOKEN_MORE;
                        break;
                case '{':
                        fxGetNextCharacter(parser);
                        parser->token2 = XS_TOKEN_LEFT_BRACE;
                        break;
                case '}':
                        fxGetNextCharacter(parser);
                        parser->token2 = XS_TOKEN_RIGHT_BRACE;
                        break;
                case '&':
                        p = fxGetNextEntity(parser, p, q);
                        break;
                default:
                        p = fxUTF8Buffer(parser, parser->character, p, q);
                        fxGetNextCharacter(parser);
                        break;
                }
        }
        parser->rawLength2 = mxPtrDiff(p - parser->buffer);
        parser->raw2 = fxNewParserString(parser, parser->buffer, parser->rawLength2);

txString fxGetNextEntity(txParser* parser, txString p, txString q)
{
        txString r = p;
        txU4 t = 0;
        *p++ = '&';
        fxGetNextCharacter(parser);
        if (parser->character == '#') {
                *p++ = '#';
                fxGetNextCharacter(parser);
                if (parser->character == 'x') {
                        *p++ = 'x';
                        fxGetNextCharacter(parser);
                        while (fxGetNextStringX(parser->character, &t)) {
                                *p++ = parser->character;
                                fxGetNextCharacter(parser);
                        }
                }
                else {
                        while (fxGetNextStringD(parser->character, &t)) {
                                *p++ = parser->character;
                                fxGetNextCharacter(parser);
                        }
                }
        }
        else {
                txEntity* entity = C_NULL;
                int c = parser->character;
                while ((p < q) && ((('0' <= c) && (c <= '9')) || (('A' <= c) && (c <= 'Z')) || (('a' <= c) && (c <= 'z')))) {
                        *p++ = c;
                        fxGetNextCharacter(parser);
                        c = parser->character;
                }
                *p = 0;
                entity = (txEntity*)bsearch(r + 1, gxEntities, XS_ENTITIES_COUNT, sizeof(txEntity), fxCompareEntities);
                t = entity ? entity->value : 0;
        }
        if (parser->character == ';') {
                *p++ = ';';
                fxGetNextCharacter(parser);
                if (t)
                        p = fxUTF8Buffer(parser, t, r, q);
        }
        return p;
}

int fuzz_oss(const uint8_t *Data, size_t Size)
{
        xsCreation _creation = {
                16 * 1024 * 1024,       /* initialChunkSize */
                16 * 1024 * 1024,       /* incrementalChunkSize */
                1 * 1024 * 1024,        /* initialHeapCount */
                1 * 1024 * 1024,        /* incrementalHeapCount */
                256 * 1024,             /* stackCount */
                256 * 1024,             /* keyCount */
                1993,                           /* nameModulo */
                127,                            /* symbolModulo */
                64 * 1024,                      /* parserBufferSize */
                1993,                           /* parserTableModulo */
        };
        size_t script_size = 0;

        char* buffer = (char *)malloc(Size + 1);
        memcpy(buffer, Data, Size);
        script_size = Size;

        buffer[script_size] = 0;        // required when debugger active

        xsCreation* creation = &_creation;
        xsMachine* machine;
        fxInitializeSharedCluster();
        machine = xsCreateMachine(creation, "xst", NULL);

        xsBeginHost(machine);
        {
                xsTry {
                        xsVars(1);

                        // hardened javascript
                        xsResult = xsNewHostFunction(fx_harden, 1);
                        xsDefine(xsGlobal, xsID("harden"), xsResult, xsDontEnum);
                        xsResult = xsNewHostFunction(fx_lockdown, 0);
                        xsDefine(xsGlobal, xsID("lockdown"), xsResult, xsDontEnum);
                        xsResult = xsNewHostFunction(fx_petrify, 1);
                        xsDefine(xsGlobal, xsID("petrify"), xsResult, xsDontEnum);
                        xsResult = xsNewHostFunction(fx_mutabilities, 1);
                        xsDefine(xsGlobal, xsID("mutabilities"), xsResult, xsDontEnum);

                        xsResult = xsNewHostFunction(fx_gc, 0);
                        xsSet(xsGlobal, xsID("gc"), xsResult);

xsSet(xsGlobal, xsID("gc"), xsResult);
                        xsResult = xsNewHostFunction(fx_print, 1);
                        xsSet(xsGlobal, xsID("print"), xsResult);

                        txSlot* realm = mxProgram.value.reference->next->value.module.realm;
                        txStringCStream aStream;
                        aStream.buffer = buffer;
                        aStream.offset = 0;
                        aStream.size = script_size;
                        fxRunScript(the, fxParseScript(the, &aStream, fxStringCGetter, mxProgramFlag | mxDebugFlag), mxRealmGlobal(realm), C_NULL, mxRealmClosures(realm)->value.reference, C_NULL, mxProgram.value.reference);
                        mxPullSlot(mxResult);
                        fxRunLoop(the);
                }
                xsCatch {
                }
        }
        xsEndHost(machine);
        fflush(stdout);
        fflush(stderr);
        xsDeleteMachine(machine);
        fxTerminateSharedCluster();
        free(buffer);
        return 0;
}
